<?php declare(strict_types=1); ?>
<section class="view hidden" id="view-admin-registrations" data-title="Event registrations" data-section="Administration">
<div class="page-heading"><div><span class="eyebrow gold-eyebrow">EVENT MANAGEMENT</span><h1>Event registrations</h1><p class="muted">Review current registration activity from the database.</p></div><button class="button button-outline" data-view="admin-events">← Back to events</button></div>
<div class="panel admin-table"><div class="table-row table-head"><span>Student</span><span>University email</span><span>Event</span><span>Registered</span><span>Status</span></div>
<?php if ($adminRegistrations === []): ?><div class="empty-state"><h3>No registrations yet</h3><p class="muted">Student event registrations will appear here.</p></div><?php else: foreach ($adminRegistrations as $registration): ?><div class="table-row"><span class="table-event"><span class="avatar blue"><?= e(strtoupper(substr((string) $registration['user_name'], 0, 2))) ?></span><strong><?= e($registration['user_name']) ?><small><?= e($registration['student_identifier'] !== '' ? 'Student ID: ' . $registration['student_identifier'] : 'Student') ?></small></strong></span><span><?= e($registration['email']) ?></span><span><a class="text-button" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $registration['event_id'] ?>"><?= e($registration['title']) ?></a></span><span><?= e(date('j M Y', strtotime((string) $registration['registered_at']))) ?></span><span class="tag <?= $registration['status'] === 'cancelled' ? 'tag-blue' : 'tag-green' ?>"><?= e(ucfirst((string) $registration['status'])) ?></span></div><?php endforeach; endif; ?></div>
</section>
